'use strict';
const fireAssets={
 'Fire zone 1':{name:'Zone 1 · Plant room',file:'fire-safety-reference.png',box:'71 118 511 262',value:'32',unit:'detectors online',note:'Smoke and heat detectors monitored. No active fire event.'},
 'Fire zone 2':{name:'Zone 2 · Data halls',file:'fire-safety-reference.png',box:'603 118 507 262',value:'47 / 48',unit:'detectors online',note:'Detector SD-042 offline for scheduled inspection.'},
 'Fire zone 3':{name:'Zone 3 · Support areas',file:'fire-safety-reference.png',box:'1130 118 517 262',value:'16',unit:'detectors online',note:'Exit routes and suppression readiness monitored.'},
 'Suppression bank':{name:'Suppression bank',file:'fire-response-reference.png',box:'80 289 398 229',value:'Ready',unit:'',note:'Clean agent cylinders and manifold pressure monitored.'},
 'Fire pump':{name:'Fire pump',file:'fire-response-reference.png',box:'494 289 398 229',value:'8.2',unit:'bar',note:'Standby duty pump and header pressure.'},
 'Fire alarm panel':{name:'Fire alarm panel',file:'fire-response-reference.png',box:'908 289 397 229',value:'Normal',unit:'',note:'Fire alarm control panel online; no fire emergency.'},
 'Emergency door':{name:'Emergency access',file:'fire-response-reference.png',box:'80 591 398 238',value:'Clear',unit:'',note:'Exit doors and access controllers monitored.'},
 'Smoke detection':{name:'Smoke detection',file:'fire-response-reference.png',box:'494 591 398 238',value:'95 / 96',unit:'online',note:'Smoke and aspirating detection network monitored.'},
 'Monitored valves':{name:'Monitored valves',file:'fire-response-reference.png',box:'908 591 397 238',value:'12 / 12',unit:'open',note:'Sprinkler and suppression valve positions supervised.'}
};
function fireMaintenance(){return state.site==='cairo'&&state.building==='DC-01'}
function fireAssetReading(asset){const a={...fireAssets[asset]};if(!fireMaintenance()){if(asset==='Fire zone 2'){a.value='48 / 48';a.note='All data-hall smoke detectors online.'}if(asset==='Smoke detection'){a.value='96 / 96';a.note='All smoke and aspirating detection devices online.'}}return a}
function fireAssetImage(asset){const a=fireAssets[asset];return `<svg class="fire-asset-image" viewBox="${a.box}" preserveAspectRatio="xMidYMid slice" role="img" aria-label="${esc(a.name)} equipment illustration"><image href="assets/${a.file}" width="1672" height="941"/></svg>`}
function firePhotoCard(asset,detailed=false){const a=fireAssetReading(asset),advisory=asset==='Fire zone 2'&&fireMaintenance();return `<article class="fire-photo-card"><div class="fire-photo-heading"><h3>${a.name}</h3>${detailed?'<span class="chip green">✓ Monitored</span>':''}</div><button class="fire-photo-button" data-equipment="${asset}" aria-label="Inspect ${esc(a.name)}">${fireAssetImage(asset)}<span class="fire-photo-inspect">Inspect equipment ↗</span></button><div class="fire-photo-caption">${detailed?`<strong>${a.value}<small>${a.unit}</small></strong><p class="${advisory?'warning':''}">${advisory?'⚠ ':''}${a.note}</p><button class="text-button" data-equipment="${asset}">Inspect equipment ↗</button>`:`<strong class="fire-response-name">${a.name}</strong><span class="${advisory?'warning':'positive'}">● ${advisory?'Maintenance advisory':'System available'}</span>`}</div></article>`}
fire=function(){const advisory=fireMaintenance();return `<div class="fire-visuals"><div class="insight-banner"><span class="fire-banner-icon">◇</span><div><strong>Fire response systems available</strong><p>No fire emergency in this simulated scenario.${advisory?' One detector has a scheduled maintenance advisory.':''}</p></div><span class="chip green">SYSTEM NORMAL</span></div><div class="fire-response-layout">${panel('Fire detection zones','Zone overlays and response equipment',`<div class="fire-response-grid">${['Suppression bank','Fire pump','Fire alarm panel','Emergency door','Smoke detection','Monitored valves'].map(a=>firePhotoCard(a)).join('')}</div>`)}${panel('Response readiness','Read-only monitoring',`<div class="detail-list"><p>Fire alarm panel<strong class="positive">Normal</strong></p><p>Smoke detectors<strong class="${advisory?'warning':'positive'}">${advisory?'95 / 96':'96 / 96'} online</strong></p><p>Suppression system<strong class="positive">Ready</strong></p><p>Fire pump<strong>Standby</strong></p><p>Header pressure<strong>8.2 bar</strong></p><p>Emergency exits<strong class="positive">Clear</strong></p><p>Valves monitored<strong class="positive">12 / 12 open</strong></p></div>${advisory?'<button class="fire-detector-advisory" data-equipment="Smoke detection">⚠ SD-042 offline · Scheduled inspection</button>':'<p class="fire-clear-note">All monitored detection devices are available.</p>'}`)}</div><h2 class="fire-safety-heading">♧ <span>Fire Safety</span> · Zones &amp; Equipment</h2><div class="fire-safety-grid">${['Fire zone 1','Fire zone 2','Fire zone 3','Suppression bank','Fire pump','Emergency door'].map(a=>firePhotoCard(a,true)).join('')}</div></div>`};
const fireOriginalScene=twinScene;
twinScene=function(kind,label,compact=false){if(!fireAssets[label])return fireOriginalScene(kind,label,compact);return `<figure class="fire-equipment-figure twin-scene ${compact?'compact':''}">${fireAssetImage(label)}</figure>`};
const fireOriginalInspector=equipmentDrawer;
equipmentDrawer=function(name){
 if(!fireAssets[name]){fireOriginalInspector(name);return}
 const a=fireAssetReading(name),advisory=fireMaintenance()&&/Fire zone 2|Smoke detection/.test(name);
 openDrawer(`<div class="eyebrow">FIRE SYSTEM / ASSET INSPECTOR</div><h2>${a.name}</h2><p>${esc(currentSite().name)} / ${state.building||'DC-01'} · Simulated telemetry</p><figure class="fire-equipment-figure">${fireAssetImage(name)}</figure>${status(advisory?'warning':'operational')}<div class="fire-inspector-reading">${a.value}<small>${a.unit}</small></div><p>${a.note}</p><div class="detail-list"><p>Fire emergency<strong>None active</strong></p><p>Monitoring<strong>Available</strong></p>${/pump/i.test(name)?'<p>Pump mode<strong>Auto / Standby</strong></p><p>Header pressure<strong>8.2 bar</strong></p>':''}${advisory?'<p>Detector<strong>SD-042 · Scheduled inspection</strong></p>':''}<p>Control mode<strong>Read-only monitoring</strong></p></div><button class="button primary" data-action="new-work">Create inspection work order</button>`);
};
